import React, { useState, useEffect } from "react";
import "./SolovievPortfolio.css";

const images = [
  "/images/pic1.jpg",
  "/images/pic2.jpg",
  "/images/pic3.jpg",
  "/images/pic4.jpg",
  "/images/pic5.jpg",
];

function SolovievPortfolio() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex((prev) => (prev + 1) % images.length);
    }, 6000);
    return () => clearInterval(timer);
  }, []);

  const scrollToSection = (id) => {
    document.getElementById(id).scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="portfolio-wrapper">
      {/* Навигация */}
      <nav className="navbar">
        <button onClick={() => scrollToSection("home")}>Главная</button>
        <button onClick={() => scrollToSection("about")}>О нас</button>
        <button onClick={() => scrollToSection("contacts")}>Контакты</button>
      </nav>

      {/* Слайдер */}
      <div className="portfolio-container" id="home">
        {images.map((img, i) => (
          <div
            key={i}
            className="background-image"
            style={{
              backgroundImage: `url(${img})`,
              opacity: i === index ? 1 : 0,
            }}
          ></div>
        ))}
        <div className="overlay"></div>
        <div className="center-content">
          <h1 className="site-title">BUILDSY.RU</h1>
          <p className="site-subtitle">ИП Соловьёв Всеволод Александрович</p>
        </div>
      </div>

      {/* Раздел "О нас" */}
      <section className="about-section" id="about">
        <h2>О нас</h2>
        <p>
          Мы предоставляем профессиональные услуги по разработке и поддержке веб-сайтов. 
          Наша команда создаёт современные и функциональные решения для бизнеса любого уровня.
        </p>
      </section>

      {/* Контакты */}
      <section className="contact-section" id="contacts">
        <h2>Контакты</h2>
        <p>📍 Адрес: г. Москва, ул. Примерная, д. 1</p>
        <p>📞 Телефон: +7 (999) 123-45-67</p>
        <p>✉ E-mail: info@buildsy.ru</p>
        <p>🌐 Сайт: <a href="https://buildsy.ru">buildsy.ru</a></p>
      </section>

      {/* Кнопка наверх */}
      <button className="scroll-top" onClick={() => scrollToSection("home")}>
        Наверх
      </button>
    </div>
  );
}

export default SolovievPortfolio;
